using FnFindFirstFileExW      = HANDLE (WINAPI*)(LPCWSTR, FINDEX_INFO_LEVELS, LPVOID, FINDEX_SEARCH_OPS, LPVOID, DWORD);
using FnFindNextFileW         = BOOL (WINAPI*)(HANDLE, LPWIN32_FIND_DATAW);
