using FnFindFirstFileExA      = HANDLE (WINAPI*)(LPCSTR, FINDEX_INFO_LEVELS, LPVOID, FINDEX_SEARCH_OPS, LPVOID, DWORD);
using FnFindNextFileA         = BOOL (WINAPI*)(HANDLE, LPWIN32_FIND_DATAA);
using FnFindClose             = BOOL (WINAPI*)(HANDLE);

struct ManifestPrefix {
    char          name[16];
    std::uint32_t fileCount;
    std::size_t   dataOffset;
};

struct ManifestHashSlot {
    std::uint64_t hash;
    std::uint32_t attrOffset;
    std::uint16_t pfxIdx;
    std::uint16_t relLen;
};
static constexpr std::size_t        kManifestHashSlots         = 1u << 20; // 1,048,576 slots
static std::vector<ManifestHashSlot> g_manifestHash;
static volatile long                g_rtAttrHits               = 0;
static volatile long                g_rtAttrMisses             = 0;
static volatile long                g_rtOpenMisses             = 0;
static volatile long                g_rtOsAttrCalls            = 0;
static volatile long                g_rtOsOpenCalls            = 0;
static volatile LONGLONG            g_rtOsWaitUs               = 0;
// Per-extension OS pass-through counters: 0=nif, 1=dds, 2=hkx, 3=tri, 4=pex, 5=cfg(ini/json/txt/xml), 6=other
static volatile long                g_rtExtOsCalls[7]          = {0};
static volatile LONGLONG            g_rtExtOsWaitUs[7]         = {0};
// --- PHYSICAL-PATH REDIRECTED OPENS, counted apart. A CreateFile* answered by opening the winning
// layer's real path (a VFS-tree hit) went into the pass-through counters above at first, so the
// old Phase 7 line's .hkx OS-call total could not say whether one of them ever
// reached USVFS. Now a successful redirect lands here and nowhere else; a physical open that FAILS (a
// stale tree entry) is counted as a failed redirect and then falls through to the counted USVFS open.
static volatile long                g_rtPhysOpenCalls          = 0;
static volatile LONGLONG            g_rtPhysOpenWaitUs         = 0;
static volatile long                g_rtPhysOpenFailed         = 0;
static volatile LONGLONG            g_rtPhysOpenFailedUs       = 0;
static volatile long                g_rtPhysExtCalls[7]        = {0};  // the seven buckets of g_rtExtOsCalls
static volatile LONGLONG            g_rtPhysExtWaitUs[7]       = {0};

// --- WHO ISSUED THE CALL: the module holding the hook's return address, i.e. whose code executed
// `call [IAT slot]`. Every plugin DLL is hooked and the profiler could not say which of them -- or the exe --
// paid the Phase 7 wait. A fixed table, sized for the exe plus every hooked plugin: each one is
// PRE-REGISTERED at hook time, before its IAT is patched, so its first pass-through already resolves with
// no loader call; anything else (another framework's trampoline, a module never walked) is resolved
// once, on first sight, outside the spinlock. A slot is published once (end/name, then base, then the
// count) and never changes, so the hot path is a lock-free range scan. Redirected opens are charged too:
// without them the .hkx question stays open if those opens were tree redirects.
struct ProfCallerSlot {
    volatile std::uintptr_t base;       // 0 = free. Written LAST, after end/name, before the count is bumped
    volatile std::uintptr_t end;        // base + SizeOfImage (base + 4 KB for code that belongs to no module)
    volatile long           attrCalls;  // GetFileAttributes* true pass-throughs
    volatile long           openCalls;  // CreateFile* true USVFS pass-throughs
    volatile long           physOpens;  // CreateFile* redirected to a physical layer path
    volatile LONGLONG       osWaitUs;   // attr + open pass-through wait
    volatile LONGLONG       physWaitUs; // redirected-open wait
    char                    name[40];   // module file name (base name), ASCII
};
static constexpr int                kProfCallerSlots           = 320;  // SkyrimSE.exe + the hooked plugins pre-registered, spare for the rest
static ProfCallerSlot               g_profCallers[kProfCallerSlots] = {};
static volatile long                g_profCallerCount          = 0;    // slots published so far
static volatile long                g_profCallerSpin           = 0;
static volatile long                g_profCallerFull           = 0;    // latched once the table is full: the hot path never asks the loader again
static volatile long                g_profCallerOverflow       = 0;    // calls charged to no slot: module unresolved, or the table full
static volatile LONGLONG            g_profCallerOverflowUs     = 0;
static int                          g_skseIatModulesHooked     = 0;
static int                          g_skseIatSlotsHooked       = 0;
static volatile long                g_oarSkippedDirs           = 0;
static volatile long                g_oarSkippedFiles          = 0;
static volatile long                g_oarAttrServed            = 0;

// --- High-Resolution Loading Profiler State ---
static CRITICAL_SECTION             g_csProf;
static bool                         g_profLockReady            = false;
static char                         g_profLogPath[MAX_PATH]    = "Data\\SKSE\\Plugins\\FleshCore.loading_profiler.log";
static double                       g_profPluginLoadStartMs    = 0.0;
static double                       g_profMeshPoolMs           = 0.0;
static double                       g_profManifestLoadMs       = 0.0;
static double                       g_profPluginLoadEndMs      = 0.0;
static double                       g_profPostLoadMs           = 0.0;
static double                       g_profPostPostLoadMs       = 0.0;
static double                       g_profInputLoadedMs        = 0.0;
static double                       g_profDataLoadedStartMs    = 0.0;
static double                       g_profLoadFillMs           = 0.0;
static double                       g_profDataLoadedEndMs      = 0.0;

struct ProfIoSnap {
    long     attrHits;
    long     attrMisses;
    long     openMisses;
    long     osAttrCalls;
    long     osOpenCalls;
    LONGLONG osWaitUs;
    long     extCalls[7];
    LONGLONG extWaitUs[7];
    // physical-path redirects, apart from the pass-throughs above
    long     physOpenCalls;
    LONGLONG physOpenWaitUs;
    long     physOpenFailed;
    LONGLONG physOpenFailedUs;
    long     physExtCalls[7];
    LONGLONG physExtWaitUs[7];
    // per caller module; a snapshot taken before a module first appeared is zero there (~9 KB a snapshot)
    long     callerCount;
    long     callerAttr[kProfCallerSlots];
    long     callerOpen[kProfCallerSlots];
    long     callerPhys[kProfCallerSlots];
    LONGLONG callerOsUs[kProfCallerSlots];
    LONGLONG callerPhysUs[kProfCallerSlots];
    long     callerOverflow;
    LONGLONG callerOverflowUs;
};

static ProfIoSnap TakeProfIoSnap()
{
    ProfIoSnap s{};
    s.attrHits    = g_rtAttrHits;
    s.attrMisses  = g_rtAttrMisses;
    s.openMisses  = g_rtOpenMisses;
    s.osAttrCalls = g_rtOsAttrCalls;
    s.osOpenCalls = g_rtOsOpenCalls;
    s.osWaitUs    = InterlockedCompareExchange64(&g_rtOsWaitUs, 0, 0);
    for (int i = 0; i < 7; ++i) {
        s.extCalls[i]  = g_rtExtOsCalls[i];
        s.extWaitUs[i] = InterlockedCompareExchange64(&g_rtExtOsWaitUs[i], 0, 0);
    }
    s.physOpenCalls    = g_rtPhysOpenCalls;
    s.physOpenWaitUs   = InterlockedCompareExchange64(&g_rtPhysOpenWaitUs, 0, 0);
    s.physOpenFailed   = g_rtPhysOpenFailed;
    s.physOpenFailedUs = InterlockedCompareExchange64(&g_rtPhysOpenFailedUs, 0, 0);
    for (int i = 0; i < 7; ++i) {
        s.physExtCalls[i]  = g_rtPhysExtCalls[i];
        s.physExtWaitUs[i] = InterlockedCompareExchange64(&g_rtPhysExtWaitUs[i], 0, 0);
    }
    s.callerCount = InterlockedCompareExchange(&g_profCallerCount, 0, 0);   // full barrier: every slot below it is complete
    if (s.callerCount > kProfCallerSlots) s.callerCount = kProfCallerSlots;
    for (long i = 0; i < s.callerCount; ++i) {
        s.callerAttr[i]   = g_profCallers[i].attrCalls;
        s.callerOpen[i]   = g_profCallers[i].openCalls;
        s.callerPhys[i]   = g_profCallers[i].physOpens;
        s.callerOsUs[i]   = InterlockedCompareExchange64(&g_profCallers[i].osWaitUs, 0, 0);
        s.callerPhysUs[i] = InterlockedCompareExchange64(&g_profCallers[i].physWaitUs, 0, 0);
    }
    s.callerOverflow   = g_profCallerOverflow;
    s.callerOverflowUs = InterlockedCompareExchange64(&g_profCallerOverflowUs, 0, 0);
    return s;
}

static double     g_profSavePreLoadStartMs = 0.0;
static double     g_profSavePreLoadEndMs   = 0.0;
static char       g_profSaveName[MAX_PATH] = {0};
static ProfIoSnap g_profSaveIoStart        = {};
static ProfIoSnap g_profBootIoStart        = {};
static ProfIoSnap g_profDataLoadedIoEnd    = {};
static std::uint32_t g_profSaveCount       = 0;
static SYSTEMTIME g_profBootStartSt        = {};
static SYSTEMTIME g_profDataLoadedEndSt    = {};
static SYSTEMTIME g_profSaveStartSt        = {};
static bool       g_profBootFinalLogged    = false;
static volatile long g_profCellLoadActive  = 0;      // crosses the RereadTicker thread and the game's: Interlocked, like g_beatInFlight
static double     g_profCellLoadStartMs    = 0.0;
static SYSTEMTIME g_profCellLoadStartSt    = {};
static ProfIoSnap g_profCellLoadIoStart    = {};
static std::uint32_t g_profCellLoadCount   = 0;

static void ProfLog(const char* fmt, ...)
{
    if (g_profLockReady) EnterCriticalSection(&g_csProf);
    FILE* f = std::fopen(g_profLogPath, "ab");
    if (f) {
        SYSTEMTIME st{};
        GetLocalTime(&st);
        std::fprintf(f, "[%02u:%02u:%02u.%03u] ",
                     unsigned(st.wHour), unsigned(st.wMinute),
                     unsigned(st.wSecond), unsigned(st.wMilliseconds));
        va_list ap;
        va_start(ap, fmt);
        std::vfprintf(f, fmt, ap);
        va_end(ap);
        std::fwrite("\r\n", 1, 2, f);
        std::fclose(f);
    }
    if (g_profLockReady) LeaveCriticalSection(&g_csProf);
}

static void LogProfIoDelta(const char* phaseName, const ProfIoSnap& s0, const ProfIoSnap& s1, double wallMs)
{
    const long dHits       = s1.attrHits    - s0.attrHits;
    const long dAttrMisses = s1.attrMisses  - s0.attrMisses;
    const long dOpenMisses = s1.openMisses  - s0.openMisses;
    const long dOsAttr     = s1.osAttrCalls - s0.osAttrCalls;
    const long dOsOpen     = s1.osOpenCalls - s0.osOpenCalls;
    const double dOsWaitMs = double(s1.osWaitUs - s0.osWaitUs) / 1000.0;
    ProfLog("  [I/O Summary - %s (%.1f ms wall)]", phaseName, wallMs);
    ProfLog("    RAM Manifest Hits (0 USVFS syscalls)         : %ld", dHits);
    ProfLog("    Authoritative Misses Blocked (Attr / Open)   : %ld / %ld (total %ld USVFS probes prevented)",
            dAttrMisses, dOpenMisses, dAttrMisses + dOpenMisses);
    // THE HISTORICAL TOTAL STAYS ON THIS LINE, so older logs read against the new ones
    // 1:1 -- and then it is split. At first a redirected open sat inside the Open column, so the Phase 7
    // reading's .hkx OS-call total could not say whether one of them ever reached USVFS. A
    // failed redirect is a stale tree entry: the physical path did not open and the call fell through.
    const long   dPhys     = s1.physOpenCalls  - s0.physOpenCalls;
    const long   dPhysFail = s1.physOpenFailed - s0.physOpenFailed;
    const double dPhysMs   = double(s1.physOpenWaitUs   - s0.physOpenWaitUs)   / 1000.0;
    const double dPhysFlMs = double(s1.physOpenFailedUs - s0.physOpenFailedUs) / 1000.0;
    ProfLog("    OS/USVFS Pass-Through Syscalls (Attr / Open) : %ld / %ld (cumulative syscall wait: %.1f ms across threads; Open = %ld true USVFS + %ld physical-layer redirects)",
            dOsAttr, dOsOpen + dPhys, dOsWaitMs + dPhysMs, dOsOpen, dPhys);
    ProfLog("      true USVFS pass-through                    : %ld attr / %ld open (%.1f ms)", dOsAttr, dOsOpen, dOsWaitMs);
    ProfLog("      physical-layer redirect opens (VFS tree)   : %ld ok (%.1f ms, %.2f ms avg) / %ld fell back to USVFS (%.1f ms wasted)",
            dPhys, dPhysMs, dPhys > 0 ? dPhysMs / double(dPhys) : 0.0, dPhysFail, dPhysFlMs);
    static const char* const kExtNames[7] = {
        ".nif/.bto/.btr", ".dds", ".hkx", ".tri", ".pex", ".ini/.json/.txt/.xml", "other"
    };
    for (int i = 0; i < 7; ++i) {
        const long   ec = s1.extCalls[i] - s0.extCalls[i];
        const double ew = double(s1.extWaitUs[i] - s0.extWaitUs[i]) / 1000.0;
        const long   pc = s1.physExtCalls[i] - s0.physExtCalls[i];
        const double pw = double(s1.physExtWaitUs[i] - s0.physExtWaitUs[i]) / 1000.0;
        if (ec > 0 || pc > 0) {
            // The first column is the earlier figure (USVFS + redirected, one
            // bucket then), so an older log's .hkx row reads 1:1
            // against this one; the split follows.
            ProfLog("      - %-20s : %7ld OS calls (%8.1f ms) = %7ld USVFS (%8.1f ms, %6.2f ms avg) + %7ld redirected opens (%8.1f ms, %6.2f ms avg)",
                    kExtNames[i], ec + pc, ew + pw, ec, ew, ec > 0 ? ew / double(ec) : 0.0, pc, pw, pc > 0 ? pw / double(pc) : 0.0);
        }
    }
    // WHO PAID. Per-caller deltas between the two snapshots, slowest first by total wait (USVFS +
    // redirected): a selection sort over at most kProfCallerSlots entries, no allocation on the heartbeat
    // thread. A module absent from this table did not pass through these hooks -- CRT/STL-routed I/O
    // (msvcp140!_Fiopen, ucrtbase fopen) never reaches them.
    long nCallers = (s1.callerCount > s0.callerCount) ? s1.callerCount : s0.callerCount;
    if (nCallers > kProfCallerSlots) nCallers = kProfCallerSlots;
    int order[kProfCallerSlots];
    int nOrder = 0;
    for (long i = 0; i < nCallers; ++i) {
        const long c = (s1.callerAttr[i] - s0.callerAttr[i]) + (s1.callerOpen[i] - s0.callerOpen[i]) + (s1.callerPhys[i] - s0.callerPhys[i]);
        if (c > 0) order[nOrder++] = int(i);
    }
    for (int a = 0; a < nOrder; ++a) {
        for (int b = a + 1; b < nOrder; ++b) {
            const LONGLONG wa = (s1.callerOsUs[order[a]] - s0.callerOsUs[order[a]]) + (s1.callerPhysUs[order[a]] - s0.callerPhysUs[order[a]]);
            const LONGLONG wb = (s1.callerOsUs[order[b]] - s0.callerOsUs[order[b]]) + (s1.callerPhysUs[order[b]] - s0.callerPhysUs[order[b]]);
            if (wb > wa) { const int t = order[a]; order[a] = order[b]; order[b] = t; }
        }
    }
    const long   dOvf   = s1.callerOverflow - s0.callerOverflow;
    const double dOvfMs = double(s1.callerOverflowUs - s0.callerOverflowUs) / 1000.0;
    if (nOrder > 0 || dOvf > 0) {
        ProfLog("    Slowest caller modules (USVFS pass-through + physical-layer redirects) - top %d of %d by cumulative wait; CRT/STL-routed I/O (msvcp140!_Fiopen, ucrtbase fopen) never reaches these hooks and is absent:",
                nOrder < 15 ? nOrder : 15, nOrder);
        for (int k = 0; k < nOrder && k < 15; ++k) {
            const int    i  = order[k];
            const long   da = s1.callerAttr[i] - s0.callerAttr[i];
            const long   dO = s1.callerOpen[i] - s0.callerOpen[i];
            const long   dp = s1.callerPhys[i] - s0.callerPhys[i];
            const double wo = double(s1.callerOsUs[i]   - s0.callerOsUs[i])   / 1000.0;
            const double wp = double(s1.callerPhysUs[i] - s0.callerPhysUs[i]) / 1000.0;
            ProfLog("      - %-36s : %6ld attr + %6ld open USVFS (%8.1f ms, %6.2f avg) | %6ld redirected (%8.1f ms, %6.2f avg)",
                    g_profCallers[i].name, da, dO, wo, (da + dO) > 0 ? wo / double(da + dO) : 0.0, dp, wp, dp > 0 ? wp / double(dp) : 0.0);
        }
        if (dOvf > 0)
            ProfLog("      - %-36s : %6ld calls (%8.1f ms)", "(unresolved module / table full)", dOvf, dOvfMs);
    }
}

static int SysTimeToDayMs(const SYSTEMTIME& st)
{
    return int(st.wHour) * 3600000 + int(st.wMinute) * 60000 + int(st.wSecond) * 1000 + int(st.wMilliseconds);
}

static SYSTEMTIME BackdateLocalTimeMs(DWORD backdateMs)
{
    FILETIME ft{};
    GetSystemTimeAsFileTime(&ft);
    ULARGE_INTEGER ui{};
    ui.LowPart  = ft.dwLowDateTime;
    ui.HighPart = ft.dwHighDateTime;
    const ULONGLONG sub = ULONGLONG(backdateMs) * 10000ULL;
    if (ui.QuadPart > sub) ui.QuadPart -= sub;
    ft.dwLowDateTime  = ui.LowPart;
    ft.dwHighDateTime = ui.HighPart;
    FILETIME ftLocal{};
    FileTimeToLocalFileTime(&ft, &ftLocal);
    SYSTEMTIME st{};
    FileTimeToSystemTime(&ftLocal, &st);
    return st;
}

static bool ParseSkseLineTimeMs(const char* line, int& outDayMs)
{
    if (!line) return false;
    for (int i = 0; line[i] && i < 64; ++i) {
        if (line[i] >= '0' && line[i] <= '9' &&
            line[i + 1] >= '0' && line[i + 1] <= '9' &&
            line[i + 2] == ':' &&
            line[i + 3] >= '0' && line[i + 3] <= '9' &&
            line[i + 4] >= '0' && line[i + 4] <= '9' &&
            line[i + 5] == ':' &&
            line[i + 6] >= '0' && line[i + 6] <= '9' &&
            line[i + 7] >= '0' && line[i + 7] <= '9') {
            const int hh = (line[i] - '0') * 10 + (line[i + 1] - '0');
            const int mm = (line[i + 3] - '0') * 10 + (line[i + 4] - '0');
            const int ss = (line[i + 6] - '0') * 10 + (line[i + 7] - '0');
            if (hh < 24 && mm < 60 && ss < 60) {
                int mmm = 0;
                if ((line[i + 8] == '.' || line[i + 8] == ',') &&
                    line[i + 9] >= '0' && line[i + 9] <= '9' &&
                    line[i + 10] >= '0' && line[i + 10] <= '9' &&
                    line[i + 11] >= '0' && line[i + 11] <= '9') {
                    mmm = (line[i + 9] - '0') * 100 + (line[i + 10] - '0') * 10 + (line[i + 11] - '0');
                }
                outDayMs = hh * 3600000 + mm * 60000 + ss * 1000 + mmm;
                return true;
            }
        }
    }
    return false;
}

struct SksePluginLogActivity {
    char name[96];
    int  firstMs;
    int  lastMs;
    int  spanMs;
    int  lineCount;
};

static void LogActiveSksePluginsInWindow(const char* phaseName, const SYSTEMTIME& stStart, const SYSTEMTIME& stEnd, double windowWallMs)
{
    const int startDayMs = SysTimeToDayMs(stStart);
    const int endDayMs   = SysTimeToDayMs(stEnd);
    const int winLo      = startDayMs - 500;
    const int winHi      = endDayMs + 500;

    FILETIME ftNow{};
    GetSystemTimeAsFileTime(&ftNow);
    ULARGE_INTEGER uiNow{};
    uiNow.LowPart  = ftNow.dwLowDateTime;
    uiNow.HighPart = ftNow.dwHighDateTime;
    const ULONGLONG maxAge100Ns = ULONGLONG(windowWallMs > 0.0 ? (windowWallMs + 30000.0) : 180000.0) * 10000ULL;
    const ULONGLONG minWriteTicks = (uiNow.QuadPart > maxAge100Ns) ? (uiNow.QuadPart - maxAge100Ns) : 0ULL;

    char dirs[2][MAX_PATH] = {{0}};
    int dirCount = 0;
    char home[MAX_PATH] = {0};
    const DWORD hn = GetEnvironmentVariableA("USERPROFILE", home, MAX_PATH);
    if (hn && hn < MAX_PATH) {
        std::snprintf(dirs[dirCount++], MAX_PATH, "%s\\Documents\\My Games\\Skyrim Special Edition\\SKSE", home);
        std::snprintf(dirs[dirCount++], MAX_PATH, "%s\\OneDrive\\Documents\\My Games\\Skyrim Special Edition\\SKSE", home);
    }

    std::vector<SksePluginLogActivity> items;
    for (int d = 0; d < dirCount; ++d) {
        if (!dirs[d][0]) continue;
        char pattern[MAX_PATH] = {0};
        std::snprintf(pattern, MAX_PATH, "%s\\*.log", dirs[d]);
        WIN32_FIND_DATAA fd{};
        HANDLE hFind = FindFirstFileA(pattern, &fd);
        if (hFind == INVALID_HANDLE_VALUE) continue;
        do {
            if (fd.dwFileAttributes & FILE_ATTRIBUTE_DIRECTORY) continue;
            if (fd.nFileSizeHigh > 0 || fd.nFileSizeLow > (16u * 1024u * 1024u)) continue;
            if (_stricmp(fd.cFileName, "FleshCore.loading_profiler.log") == 0 ||
                _stricmp(fd.cFileName, "FleshCore.loading_profiler.prev.log") == 0) continue;
            const std::size_t fnLen = std::strlen(fd.cFileName);
            if (fnLen > 9 && _stricmp(fd.cFileName + fnLen - 9, ".prev.log") == 0) continue;
            if (fnLen > 8 && _stricmp(fd.cFileName + fnLen - 8, ".bak.log") == 0) continue;

            ULARGE_INTEGER uiWrite{};
            uiWrite.LowPart  = fd.ftLastWriteTime.dwLowDateTime;
            uiWrite.HighPart = fd.ftLastWriteTime.dwHighDateTime;
            if (uiWrite.QuadPart < minWriteTicks) continue;

            char fullPath[MAX_PATH] = {0};
            std::snprintf(fullPath, MAX_PATH, "%s\\%s", dirs[d], fd.cFileName);
            FILE* f = std::fopen(fullPath, "rb");
            if (!f) continue;

            int firstMs  = -1;
            int lastMs   = -1;
            int activeMs = 0;
            int lines    = 0;
            char line[1024];
            while (std::fgets(line, sizeof(line), f)) {
                int tMs = 0;
                if (ParseSkseLineTimeMs(line, tMs)) {
                    bool inWin = false;
                    if (winHi >= winLo) {
                        inWin = (tMs >= winLo && tMs <= winHi);
                    } else {
                        inWin = (tMs >= winLo || tMs <= (winHi + 86400000));
                    }
                    if (inWin) {
                        if (firstMs < 0) firstMs = tMs;
                        if (lastMs >= 0 && tMs >= lastMs && (tMs - lastMs) <= 15000) {
                            activeMs += (tMs - lastMs);
                        }
                        lastMs = tMs;
                        ++lines;
                    }
                }
            }
            std::fclose(f);

            if (lines > 0) {
                SksePluginLogActivity act{};
                std::strncpy(act.name, fd.cFileName, sizeof(act.name) - 1);
                act.name[sizeof(act.name) - 1] = '\0';
                act.firstMs   = firstMs;
                act.lastMs    = lastMs;
                act.spanMs    = activeMs;
                act.lineCount = lines;
                items.push_back(act);
            }
        } while (FindNextFileA(hFind, &fd));
        FindClose(hFind);
    }

    for (std::size_t i = 0; i < items.size(); ++i) {
        for (std::size_t j = i + 1; j < items.size(); ++j) {
            if (items[j].spanMs > items[i].spanMs ||
                (items[j].spanMs == items[i].spanMs && items[j].lineCount > items[i].lineCount)) {
                SksePluginLogActivity tmp = items[i];
                items[i] = items[j];
                items[j] = tmp;
            }
        }
    }

    ProfLog("  [Cross-Plugin SKSE Log Activity - %s (%02u:%02u:%02u.%03u -> %02u:%02u:%02u.%03u)]",
            phaseName,
            unsigned(stStart.wHour), unsigned(stStart.wMinute), unsigned(stStart.wSecond), unsigned(stStart.wMilliseconds),
            unsigned(stEnd.wHour), unsigned(stEnd.wMinute), unsigned(stEnd.wSecond), unsigned(stEnd.wMilliseconds));
    if (items.empty()) {
        ProfLog("    (No timestamped SKSE plugin log lines written during this window -- engine C++/BSA/cell work)");
        return;
    }
    const std::size_t limit = items.size() < 15 ? items.size() : 15;
    for (std::size_t i = 0; i < limit; ++i) {
        const SksePluginLogActivity& a = items[i];
        const int fH = (a.firstMs / 3600000) % 24, fM = (a.firstMs / 60000) % 60, fS = (a.firstMs / 1000) % 60, fMs = a.firstMs % 1000;
        const int lH = (a.lastMs  / 3600000) % 24, lM = (a.lastMs  / 60000) % 60, lS = (a.lastMs  / 1000) % 60, lMs = a.lastMs  % 1000;
        ProfLog("    - %-36s : %7.2f s span (%02d:%02d:%02d.%03d -> %02d:%02d:%02d.%03d, %d log lines)",
                a.name, double(a.spanMs) / 1000.0,
                fH, fM, fS, fMs, lH, lM, lS, lMs, a.lineCount);
    }
}

static void ProfOnHeartbeatTick(DWORD age, bool loadScreenUp)
{
    if (!g_profBootFinalLogged) return;
    if (loadScreenUp) {
        InterlockedExchange(&g_profCellLoadActive, 0);
        return;
    }
    if (!InterlockedCompareExchange(&g_profCellLoadActive, 0, 0) && age >= 1500u) {
        g_profCellLoadStartMs = NowMs() - double(age);
        g_profCellLoadStartSt = BackdateLocalTimeMs(age);
        g_profCellLoadIoStart = TakeProfIoSnap();          // 9,224 B written while the flag is down: no reader can be inside it
        InterlockedExchange(&g_profCellLoadActive, 1);    // full barrier: the three globals are complete before any reader sees the flag
    }
}

static void ProfOnHeartbeatMainThread()
{
    if (!g_profBootFinalLogged && g_profDataLoadedEndMs > 0.0) {
        g_profBootFinalLogged = true;
        const double mainMenuReadyMs = NowMs();
        SYSTEMTIME stEnd{};
        GetLocalTime(&stEnd);
        const ProfIoSnap ioEnd = TakeProfIoSnap();
        const double lateDataLoadedMs = mainMenuReadyMs - g_profDataLoadedEndMs;
        const double fullBootMs       = mainMenuReadyMs - g_profPluginLoadStartMs;
        const double fcBootTotalMs    = (g_profPluginLoadEndMs - g_profPluginLoadStartMs) +
                                        (g_profDataLoadedEndMs - g_profDataLoadedStartMs);
        const double fcFullPct        = (fullBootMs > 0.0) ? (fcBootTotalMs * 100.0 / fullBootMs) : 0.0;
        ProfLog("================================================================================");
        ProfLog("[STARTUP PROFILER - PART 2] Late kDataLoaded Plugins -> Main Menu Ready : %.1f ms (%.2f s)",
                lateDataLoadedMs, lateDataLoadedMs / 1000.0);
        ProfLog("  Phase 7: Post-FleshCore kDataLoaded Plugins (other SKSE DLLs)       : %8.1f ms (%.2f s)",
                lateDataLoadedMs, lateDataLoadedMs / 1000.0);
        ProfLog("    - OAR Mesh Filter Skipped (Final Startup Count)                   : %ld non-OAR dirs, %ld non-OAR files (%ld RAM attrs)",
                g_oarSkippedDirs, g_oarSkippedFiles, g_oarAttrServed);
        ProfLog("  -> TRUE TOTAL STARTUP TIME (SKSEPlugin_Load -> Main Menu Ready)     : %8.1f ms (%.2f s)",
                fullBootMs, fullBootMs / 1000.0);
        ProfLog("  -> FleshCore Total Active Startup Time                              : %8.1f ms (%.2f%% of true startup)",
                fcBootTotalMs, fcFullPct);
        ProfLog("  -> Engine + Other Mods Total Startup Time                           : %8.1f ms (%.2f%% of true startup)",
                fullBootMs - fcBootTotalMs, 100.0 - fcFullPct);
        LogProfIoDelta("Phase 7 (Late kDataLoaded -> Main Menu)", g_profDataLoadedIoEnd, ioEnd, lateDataLoadedMs);
        LogActiveSksePluginsInWindow("Phase 7 (Late kDataLoaded -> Main Menu)", g_profDataLoadedEndSt, stEnd, lateDataLoadedMs);
        LogActiveSksePluginsInWindow("Full Startup (SKSEPlugin_Load -> Main Menu)", g_profBootStartSt, stEnd, fullBootMs);
        return;
    }
    if (InterlockedCompareExchange(&g_profCellLoadActive, 0, 0)) {
        const ProfIoSnap io0     = g_profCellLoadIoStart;    // the ticker rewrites these only while the flag is down,
        const double     startMs = g_profCellLoadStartMs;    // and it may put the flag down and re-arm within this same task if
        const SYSTEMTIME stStart = g_profCellLoadStartSt;    // the report below stalls >= 1.5 s -- so copy first, clear second
        InterlockedExchange(&g_profCellLoadActive, 0);       // full barrier: the copies are complete before the ticker may write again
        if (LoadScreenUp()) return;
        const double endMs  = NowMs();
        const double wallMs = endMs - startMs;
        if (wallMs >= 2000.0) {
            SYSTEMTIME stEnd{};
            GetLocalTime(&stEnd);
            const ProfIoSnap ioEnd = TakeProfIoSnap();
            ++g_profCellLoadCount;
            ProfLog("================================================================================");
            ProfLog("[CELL TRANSITION / IN-GAME LOADING SCREEN #%u] Total Wall Time: %.1f ms (%.2f s)",
                    g_profCellLoadCount, wallMs, wallMs / 1000.0);
            LogProfIoDelta("Cell Transition / Door Load", io0, ioEnd, wallMs);
            LogActiveSksePluginsInWindow("Cell Transition / Door Load", stStart, stEnd, wallMs);
        }
    }
}

static int ClassifyExtIdxA(LPCSTR path)
{
    if (!path) return 6;
    const char* dot = nullptr;
    for (const char* p = path; *p; ++p) {
        if (*p == '\\' || *p == '/') dot = nullptr;
        else if (*p == '.') dot = p + 1;
    }
    if (!dot || !*dot) return 6;
    if (_stricmp(dot, "nif") == 0 || _stricmp(dot, "bto") == 0 || _stricmp(dot, "btr") == 0) return 0;
    if (_stricmp(dot, "dds") == 0) return 1;
    if (_stricmp(dot, "hkx") == 0) return 2;
    if (_stricmp(dot, "tri") == 0) return 3;
    if (_stricmp(dot, "pex") == 0) return 4;
    if (_stricmp(dot, "ini") == 0 || _stricmp(dot, "json") == 0 || _stricmp(dot, "txt") == 0 || _stricmp(dot, "xml") == 0) return 5;
    return 6;
}

static int ClassifyExtIdxW(LPCWSTR path)
{
    if (!path) return 6;
    const wchar_t* dot = nullptr;
    for (const wchar_t* p = path; *p; ++p) {
        if (*p == L'\\' || *p == L'/') dot = nullptr;
        else if (*p == L'.') dot = p + 1;
    }
    if (!dot || !*dot) return 6;
    if (_wcsicmp(dot, L"nif") == 0 || _wcsicmp(dot, L"bto") == 0 || _wcsicmp(dot, L"btr") == 0) return 0;
    if (_wcsicmp(dot, L"dds") == 0) return 1;
    if (_wcsicmp(dot, L"hkx") == 0) return 2;
    if (_wcsicmp(dot, L"tri") == 0) return 3;
    if (_wcsicmp(dot, L"pex") == 0) return 4;
    if (_wcsicmp(dot, L"ini") == 0 || _wcsicmp(dot, L"json") == 0 || _wcsicmp(dot, L"txt") == 0 || _wcsicmp(dot, L"xml") == 0) return 5;
    return 6;
}

// THE HOOK'S RETURN ADDRESS: the instruction after the caller's `call [IAT slot]`, inside the
// module whose code asked. MSVC spells it _ReturnAddress(); GCC/MinGW __builtin_return_address(0). The
// hooks are address-taken (they live in IAT slots) and never inlined, so evaluated in their own frame it
// names the caller, not FleshCore.
#if defined(_MSC_VER)
#define FC_RETURN_ADDRESS() _ReturnAddress()
#else
#define FC_RETURN_ADDRESS() __builtin_return_address(0)
#endif

// ONE CALLER RANGE, PUBLISHED. Under g_profCallerSpin and nothing else; never asks the loader.
// Publish order: the fields, then base, then the count -- a reader that sees the count sees a whole slot.
// A full table latches g_profCallerFull, and from then on the hot path never asks the loader again.
static void ProfRegisterCallerRange(std::uintptr_t base, std::uintptr_t end, const char* displayName)
{
    if (!base || end <= base) return;
    while (InterlockedCompareExchange(&g_profCallerSpin, 1, 0) != 0) YieldProcessor();
    bool known = false;
    for (long i = 0; i < g_profCallerCount; ++i) {
        if (g_profCallers[i].base == base) { known = true; break; }
    }
    if (!known) {
        if (g_profCallerCount < kProfCallerSlots) {
            ProfCallerSlot& s = g_profCallers[g_profCallerCount];
            s.end = end; s.attrCalls = 0; s.openCalls = 0; s.physOpens = 0; s.osWaitUs = 0; s.physWaitUs = 0;
            std::snprintf(s.name, sizeof(s.name), "%s", displayName ? displayName : "(unknown)");
            s.base = base;
            InterlockedIncrement(&g_profCallerCount);
        } else {
            InterlockedExchange(&g_profCallerFull, 1);
        }
    }
    InterlockedExchange(&g_profCallerSpin, 0);
}

// A MODULE, FROM ITS PE HEADER. Called at hook time for every module whose IAT is about to be
// patched -- SkyrimSE.exe in InstallStartupInvalidationOpt, each plugin in InstallSksePluginIatHooks --
// so its first pass-through resolves with no loader call; and from the cold path below for the rest.
static void ProfRegisterCallerModule(HMODULE hMod, const char* displayName)
{
    if (!hMod) return;
    const std::uintptr_t base = reinterpret_cast<std::uintptr_t>(hMod);
    std::uintptr_t end = base + 0x1000;
    const auto* dos = reinterpret_cast<const IMAGE_DOS_HEADER*>(base);
    if (Readable(dos, sizeof(IMAGE_DOS_HEADER)) && dos->e_magic == IMAGE_DOS_SIGNATURE) {
        const auto* nt = reinterpret_cast<const IMAGE_NT_HEADERS64*>(base + dos->e_lfanew);
        if (Readable(nt, sizeof(IMAGE_NT_HEADERS64)) && nt->Signature == IMAGE_NT_SIGNATURE)
            end = base + nt->OptionalHeader.SizeOfImage;
    }
    ProfRegisterCallerRange(base, end, displayName);
}

enum { kProfCallAttr = 0, kProfCallOpen = 1, kProfCallPhysOpen = 2 };

// One call, charged to the module that contains the hook's return address. Hot path: a lock-free
// range scan over the published slots -- tens of nanoseconds against a syscall that cost 0.5-14 ms in
// testing. Cold path, once per unknown module (or per 4 KB page of code that belongs to no module -- another
// framework's trampoline): resolve OUTSIDE any spinlock, publish, rescan. Once the table is full the latch
// keeps the loader out of the hot path for good and the call is counted as overflow instead. Never reached
// on a RAM hit.
static void RecordOsCaller(const void* retAddr, int kind, LONGLONG us)
{
    const std::uintptr_t pc = reinterpret_cast<std::uintptr_t>(retAddr);
    for (int pass = 0; pass < 2; ++pass) {
        long published = g_profCallerCount;      // bumped last, behind a full barrier; the slot fields are volatile
        if (published > kProfCallerSlots) published = kProfCallerSlots;
        for (long i = 0; i < published; ++i) {
            if (pc >= g_profCallers[i].base && pc < g_profCallers[i].end) {
                ProfCallerSlot& s = g_profCallers[i];
                if (kind == kProfCallPhysOpen) {
                    InterlockedIncrement(&s.physOpens);
                    if (us > 0) InterlockedAdd64(&s.physWaitUs, us);
                } else {
                    InterlockedIncrement(kind == kProfCallAttr ? &s.attrCalls : &s.openCalls);
                    if (us > 0) InterlockedAdd64(&s.osWaitUs, us);
                }
                return;
            }
        }
        if (pass == 1 || !retAddr || g_profCallerFull) break;
        HMODULE hMod = nullptr;
        if (GetModuleHandleExW(GET_MODULE_HANDLE_EX_FLAG_FROM_ADDRESS | GET_MODULE_HANDLE_EX_FLAG_UNCHANGED_REFCOUNT,
                               reinterpret_cast<LPCWSTR>(retAddr), &hMod) && hMod) {
            char path[MAX_PATH] = {0};
            const char* bn = "(unknown module)";
            if (GetModuleFileNameA(hMod, path, MAX_PATH) > 0) {
                bn = path;
                for (const char* p = path; *p; ++p) if (*p == '\\' || *p == '/') bn = p + 1;
            }
            ProfRegisterCallerModule(hMod, bn);
        } else {
            const std::uintptr_t page = pc & ~std::uintptr_t(0xFFF);
            ProfRegisterCallerRange(page, page + 0x1000, "(non-module code / trampoline)");
        }
    }
    InterlockedIncrement(&g_profCallerOverflow);
    if (us > 0) InterlockedAdd64(&g_profCallerOverflowUs, us);
}

static void RecordOsIo(int extIdx, double dtMs, bool isOpen, const void* retAddr)
{
    if (isOpen) InterlockedIncrement(&g_rtOsOpenCalls);
    else        InterlockedIncrement(&g_rtOsAttrCalls);
    const LONGLONG us = static_cast<LONGLONG>(dtMs * 1000.0);
    if (us > 0) {
        InterlockedAdd64(&g_rtOsWaitUs, us);
        if (extIdx >= 0 && extIdx < 7) {
            InterlockedIncrement(&g_rtExtOsCalls[extIdx]);
            InterlockedAdd64(&g_rtExtOsWaitUs[extIdx], us);
        }
    } else if (extIdx >= 0 && extIdx < 7) {
        InterlockedIncrement(&g_rtExtOsCalls[extIdx]);
    }
    RecordOsCaller(retAddr, isOpen ? kProfCallOpen : kProfCallAttr, us);   // who asked
}

// A redirected open: the winning layer's real path was opened instead of the USVFS virtual one,
// and it is charged to its caller like any other -- or the .hkx question stays open. `opened` false is a
// stale tree entry: the time was spent, nothing came of it, and it is NOT attributed; the USVFS open that
// follows is, by RecordOsIo.
static void RecordPhysIo(int extIdx, double dtMs, bool opened, const void* retAddr)
{
    const LONGLONG us = static_cast<LONGLONG>(dtMs * 1000.0);
    if (!opened) {
        InterlockedIncrement(&g_rtPhysOpenFailed);
        if (us > 0) InterlockedAdd64(&g_rtPhysOpenFailedUs, us);
        return;
    }
    InterlockedIncrement(&g_rtPhysOpenCalls);
    if (us > 0) InterlockedAdd64(&g_rtPhysOpenWaitUs, us);
    if (extIdx >= 0 && extIdx < 7) {
        InterlockedIncrement(&g_rtPhysExtCalls[extIdx]);
        if (us > 0) InterlockedAdd64(&g_rtPhysExtWaitUs[extIdx], us);
    }
    RecordOsCaller(retAddr, kProfCallPhysOpen, us);
}

